#include "proof/fraig/fraigInt.h"
#include <stdio.h>
int main(void) {for(int k=0;k<2;k++){int limit=k?-1:1;Fraig_Params_t params;Fraig_ParamsSetDefault(&params);params.fFuncRed=0;Fraig_Man_t*p=Fraig_ManCreate(&params);Fraig_Node_t*x[5][4];for(int i=0;i<5;i++)for(int j=0;j<4;j++)x[i][j]=Fraig_ManReadIthVar(p,4*i+j);Fraig_Node_t*root=p->pConst1;for(int i=0;i<5;i++){Fraig_Node_t*r=Fraig_Not(p->pConst1);for(int j=0;j<4;j++)r=Fraig_NodeOr(p,r,x[i][j]);root=Fraig_NodeAnd(p,root,r);}for(int j=0;j<4;j++)for(int i=0;i<5;i++)for(int h=0;h<i;h++)root=Fraig_NodeAnd(p,root,Fraig_NodeOr(p,Fraig_Not(x[i][j]),Fraig_Not(x[h][j])));Fraig_Node_t*node=Fraig_Regular(root);int result=Fraig_NodeIsEquivalent(p,p->pConst1,node,limit,0);printf("limit=%d result=%d failures=%d failTfo=%d\n",limit,result,p->nSatFailsReal,node->fFailTfo);Fraig_ManFree(p);} }
